import {
  DeltakerEndring,
  EndrePrisinfoStatus,
  Endring,
  EndringType
} from '../../model/deltakerHistorikk.ts'
import { formatDate } from '../../utils/utils.ts'
import { HistorikkElement } from './HistorikkElement.tsx'
import { getEndringsTittel } from '../../utils/displayText.ts'
import { Detail, ReadMore, Tag } from '@navikt/ds-react'

export const erTilbakekaltPrisinfo = (
  endring: Endring
): endring is Extract<Endring, { type: EndringType.EndrePrisinfo }> =>
  endring.type === EndringType.EndrePrisinfo &&
  endring.status === EndrePrisinfoStatus.TILBAKEKALT

export const TilbakekaltPrisinfoEndring = ({
  deltakerEndring,
  erEnkeltplass,
  icon,
  endringsDetaljer
}: {
  deltakerEndring: DeltakerEndring
  erEnkeltplass: boolean
  icon: React.ReactNode
  endringsDetaljer: React.JSX.Element
}) => {
  const endring = deltakerEndring.endring

  return (
    <HistorikkElement
      tittel={getEndringsTittel(endring, erEnkeltplass)}
      icon={icon}
      badge={
        <Tag variant="outline" data-color="neutral" size="small">
          Tilbakekalt
        </Tag>
      }
    >
      <Detail className="mt-1" textColor="subtle">
        {`Tilbakekalt ${formatDate(deltakerEndring.endret)} av ${deltakerEndring.endretAv} ${deltakerEndring.endretAvEnhet}.`}
      </Detail>

      <ReadMore
        variant="moderate"
        size="small"
        className="mt-2"
        header="Endringen som ble tilbakekalt"
      >
        {endringsDetaljer}
      </ReadMore>
    </HistorikkElement>
  )
}
