import { BodyLong, Heading, Link, List } from '@navikt/ds-react'
import { Prisinformasjon, PrisinformasjonType } from '../model/prisinformasjon'
import { TILLEGGSSTONADER_URL } from '../utils/constants'
import { getPrisInformasjonTekst } from '../utils/displayText'
import { beregnEstimertTotalsum, NOK_FORMATTER } from '../utils/utils'

interface Props {
  prisinformasjon?: Prisinformasjon | null
  headinglevel: '2' | '3'
  headingsize?: 'medium' | 'small'
  showHeading?: boolean
  compact?: boolean
  visTilleggsstonaderInfo?: boolean
  className?: string
}

export const PrisOgBetaling = ({
  prisinformasjon,
  headinglevel,
  headingsize = 'medium',
  showHeading = true,
  visTilleggsstonaderInfo = true,
  compact = false,
  className
}: Props) => {
  if (!prisinformasjon) {
    return null
  }

  const renderPrisinformasjon = () => {
    switch (prisinformasjon.type) {
      case PrisinformasjonType.Anskaffelse:
        return (
          <>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-0' : 'mt-2'} whitespace-pre-wrap`}
            >
              Nav har kjøpt en plass hos opplæringsstedet. Nav betaler for
              opplæringen.
            </BodyLong>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-2' : 'mt-4'} whitespace-pre-wrap`}
            >
              Totalkostnaden er {NOK_FORMATTER.format(prisinformasjon.pris)}{' '}
              kroner.
            </BodyLong>
          </>
        )
      case PrisinformasjonType.Tilskudd:
        return (
          <>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-0' : 'mt-2'} whitespace-pre-wrap`}
            >
              Du kan få tilskudd til å dekke disse utgiftene:
            </BodyLong>
            <List className={`${compact ? 'mt-2' : 'mt-4'}`} size="small">
              {prisinformasjon.tilskudd.map((tilskudd) => (
                <List.Item key={tilskudd.type}>
                  {getPrisInformasjonTekst(tilskudd.type)}:{' '}
                  {NOK_FORMATTER.format(tilskudd.pris)} kroner
                </List.Item>
              ))}
            </List>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-2' : 'mt-4'} whitespace-pre-wrap`}
            >
              Totalt anslått tilskudd:{' '}
              {NOK_FORMATTER.format(beregnEstimertTotalsum(prisinformasjon))}{' '}
              kroner.
            </BodyLong>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-2' : 'mt-4'} whitespace-pre-wrap`}
            >
              Utbetaling skjer når utgiftene er dokumentert.
            </BodyLong>

            {prisinformasjon.tilleggsopplysninger && (
              <BodyLong
                size="small"
                className={`${compact ? 'mt-2' : 'mt-4'} whitespace-pre-wrap`}
              >
                {prisinformasjon.tilleggsopplysninger}
              </BodyLong>
            )}
          </>
        )
      case PrisinformasjonType.IngenKostnader:
        return (
          <>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-0' : 'mt-2'} whitespace-pre-wrap`}
            >
              Nav skal ikke betale for opplæringen.
            </BodyLong>
            <BodyLong
              size="small"
              className={`${compact ? 'mt-2' : 'mt-4'} whitespace-pre-wrap`}
            >
              {prisinformasjon.tilleggsopplysninger}
            </BodyLong>
          </>
        )
      default:
        return null
    }
  }

  return (
    <div className={className ?? ''}>
      {showHeading && (
        <Heading level={headinglevel} size={headingsize}>
          Pris og betalingsbetingelser
        </Heading>
      )}

      {renderPrisinformasjon()}

      {prisinformasjon.begrunnelse && (
        <BodyLong
          size="small"
          className={`${compact ? 'mt-2' : 'mt-4'} whitespace-pre-wrap`}
        >
          Navs begrunnelse: {prisinformasjon.begrunnelse}
        </BodyLong>
      )}

      {visTilleggsstonaderInfo && (
        <BodyLong size="small" className="mt-4 whitespace-pre-wrap">
          Les mer om støtte til andre utgifter knyttet til opplæringen på{' '}
          <Link href={TILLEGGSSTONADER_URL}>nav.no/tilleggsstønader</Link>.
        </BodyLong>
      )}
    </div>
  )
}
