import { Label, TextField } from '@navikt/ds-react'
import { Ref, forwardRef } from 'react'

export interface NumberTextFieldProps {
  id: string
  className?: string
  containerClassName?: string
  labelClassName?: string
  label: string
  aria_label?: string
  description?: string
  inlineLabel?: boolean
  disabled: boolean
  value?: number
  error?: boolean | string
  required?: boolean
  onChange: (newValue: number | undefined) => void
}

const fjernMellomrom = (verdi: string) => verdi.replace(/\s/g, '')

const NumberTextFieldComponent = (
  {
    id,
    className,
    containerClassName,
    labelClassName,
    label,
    aria_label,
    description,
    inlineLabel,
    disabled,
    value,
    error,
    required,
    onChange
  }: NumberTextFieldProps,
  ref: Ref<HTMLInputElement>
) => {
  const textField = (
    <TextField
      ref={ref}
      label={inlineLabel ? '' : label}
      aria-label={aria_label ?? (inlineLabel ? '' : label)}
      description={description}
      size="small"
      disabled={disabled}
      inputMode="numeric"
      pattern="[0-9]*"
      value={value ?? ''}
      onChange={({ target }) => {
        const verdiUtenMellomrom = fjernMellomrom(target.value)
        const intValue = parseInt(verdiUtenMellomrom)
        if (!Number.isNaN(intValue)) onChange(intValue)
        else if (verdiUtenMellomrom === '') onChange(undefined)
        else onChange(value)
      }}
      error={error}
      aria-required={required}
      id={id}
      className={className ?? ''}
    />
  )

  if (inlineLabel) {
    return (
      <div className={`flex items-center gap-3 ${containerClassName ?? ''}`}>
        <Label htmlFor={id} size="small" className={labelClassName ?? 'mb-0'}>
          {label}
        </Label>
        {textField}
      </div>
    )
  }

  return <div className={containerClassName ?? ''}>{textField}</div>
}

export const NumberTextField = forwardRef<
  HTMLInputElement,
  NumberTextFieldProps
>(NumberTextFieldComponent)
